 bool ParseDue(string input,out long ticks){ticks=0;if(string.IsNullOrWhiteSpace(input))return true;if(!DateTime.TryParse(input,tr,DateTimeStyles.AllowWhiteSpaces,out var value)&&!DateTime.TryParse(input,CultureInfo.GetCultureInfo("tr-TR"),DateTimeStyles.AllowWhiteSpaces,out value))return false;if(value<DateTime.Now&&input.Trim().Length<=5)value=value.AddDays(1);ticks=new DateTimeOffset(value).UtcTicks;return true;}
